					contentJSON: withCtx(() => _cache[16] || (_cache[16] = [createTextVNode("{ \"Grove_Buzzer_v1.1_minimal\": { \"example_path\": \"public/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Grove_Buzzer_v1.1_minimal\", \"example_url\": \"https://github.com/Make-Your-School/mks-SeeedStudio-Grove_Buzzer_v1.1/tree/main/examples/Grove_Buzzer_v1.1_minimal\", \"example_path_app\": \"/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Grove_Buzzer_v1.1_minimal/\", \"files\": { \"Grove_Buzzer_v1.1_minimal.ino\": { \"file_url\": \"https://github.com/Make-Your-School/mks-SeeedStudio-Grove_Buzzer_v1.1/tree/main/examples/Grove_Buzzer_v1.1_minimal/Grove_Buzzer_v1.1_minimal.ino\", \"file_path\": \"public/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Grove_Buzzer_v1.1_minimal/Grove_Buzzer_v1.1_minimal.ino\", \"file_path_web\": \"/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Grove_Buzzer_v1.1_minimal/Grove_Buzzer_v1.1_minimal.ino\", \"example_path_app\": \"/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Grove_Buzzer_v1.1_minimal/\", \"file_name\": \"Grove_Buzzer_v1.1_minimal.ino\", \"name\": \"Grove_Buzzer_v1.1_minimal.\", \"file_ext\": \"ino\", \"content\": \"// schließe den Summer an Pin D6 des Grove-Shields an.\\n// lade den sketch hoch\\n// der Summer sollte nun im 1-Sekunden Takt Piepen.\\n\\nvoid setup() {\\n    // Setze digitaler Pin 6 als Output für den Summer\\n    pinMode(6, OUTPUT);\\n}\\n\\nvoid loop() {\\n    // Mache Summer an\\n    digitalWrite(6, HIGH);\\n    // Warte eine Sekunde\\n    delay(1000);\\n    // Mache Summer aus\\n    digitalWrite(6, LOW);\\n    // Warte eine Sekunde\\n    delay(1000);\\n}\\n\" } } }, \"Summer_Melodie\": { \"example_path\": \"public/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Summer_Melodie\", \"example_url\": \"https://github.com/Make-Your-School/mks-SeeedStudio-Grove_Buzzer_v1.1/tree/main/examples/Summer_Melodie\", \"example_path_app\": \"/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Summer_Melodie/\", \"files\": { \"Summer_Melodie.ino\": { \"file_url\": \"https://github.com/Make-Your-School/mks-SeeedStudio-Grove_Buzzer_v1.1/tree/main/examples/Summer_Melodie/Summer_Melodie.ino\", \"file_path\": \"public/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Summer_Melodie/Summer_Melodie.ino\", \"file_path_web\": \"/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Summer_Melodie/Summer_Melodie.ino\", \"example_path_app\": \"/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Summer_Melodie/\", \"file_name\": \"Summer_Melodie.ino\", \"name\": \"Summer_Melodie.\", \"file_ext\": \"ino\", \"content\": \"/*\\n Buzzer\\n Das ist ein Beispiel damit der Summer Melodien spielen kann.\\n Weitere Informationen in Englisch:\\n\\n The circuit:\\n * Buzzer attached to pin 6\\n * one side pin (either one) to ground\\n * the other side pin to VCC\\n * LED anode (long leg) attached to RED_LED\\n * LED cathode (short leg) attached to ground\\n\\n * Note:\\n This example code is in the public domain.\\n\\n https://www.seeedstudio.com/wiki/index.php?title=GROVE_-_Starter_Kit_v1.1b#Grove_-_Buzzer\\n\\n*/\\n\\n/* Macro Define */\\n#define BUZZER_PIN 6 \\n\\nint length = 15;         /* the number of notes */\\nchar notes[] = \\\"ccggaagffeeddc \\\";\\nint beats[] = { 1, 1, 1, 1, 1, 1, 2, 1, 1, 1, 1, 1, 1, 2, 4 };\\nint tempo = 300;\\n\\nvoid setup()\\n{\\n    /* set buzzer pin as output */\\n    pinMode(BUZZER_PIN, OUTPUT);\\n}\\n\\nvoid loop()\\n{\\n    for(int i = 0; i < length; i++) {\\n        if(notes[i] == ' ') {\\n            delay(beats[i] * tempo);\\n        } else {\\n            playNote(notes[i], beats[i] * tempo);\\n        }\\n        delay(tempo / 2);    /* delay between notes */\\n    }\\n\\n}\\n\\n/* play tone */\\nvoid playTone(int tone, int duration) {\\n    for (long i = 0; i < duration * 1000L; i += tone * 2) {\\n        digitalWrite(BUZZER_PIN, HIGH);\\n        delayMicroseconds(tone);\\n        digitalWrite(BUZZER_PIN, LOW);\\n        delayMicroseconds(tone);\\n    }\\n}\\n\\nvoid playNote(char note, int duration) {\\n    char names[] = { 'c', 'd', 'e', 'f', 'g', 'a', 'b', 'C' };\\n    int tones[] = { 1915, 1700, 1519, 1432, 1275, 1136, 1014, 956 };\\n\\n    // play the tone corresponding to the note name\\n    for (int i = 0; i < 8; i++) {\\n        if (names[i] == note) {\\n            playTone(tones[i], duration);\\n        }\\n    }\\n}\" } } }, \"Summer_Standardcode\": { \"example_path\": \"public/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Summer_Standardcode\", \"example_url\": \"https://github.com/Make-Your-School/mks-SeeedStudio-Grove_Buzzer_v1.1/tree/main/examples/Summer_Standardcode\", \"example_path_app\": \"/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Summer_Standardcode/\", \"files\": { \"Summer_Standardcode.ino\": { \"file_url\": \"https://github.com/Make-Your-School/mks-SeeedStudio-Grove_Buzzer_v1.1/tree/main/examples/Summer_Standardcode/Summer_Standardcode.ino\", \"file_path\": \"public/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Summer_Standardcode/Summer_Standardcode.ino\", \"file_path_web\": \"/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Summer_Standardcode/Summer_Standardcode.ino\", \"example_path_app\": \"/mks/parts/mks-SeeedStudio-Grove_Buzzer_v1.1/examples/Summer_Standardcode/\", \"file_name\": \"Summer_Standardcode.ino\", \"name\": \"Summer_Standardcode.\", \"file_ext\": \"ino\", \"content\": \"#define SUMMER_PIN 6  // must be a PWM pin\\n#define LAUTSTAERKE 8 // Wie laut es ist, von 0 - 255\\n\\nvoid setup() {\\n  // Setze den Summer Pin auf Output\\n  pinMode(SUMMER_PIN, OUTPUT);\\n}\\n\\nvoid loop() {\\n  // Mache den Summer an\\n  analogWrite(SUMMER_PIN, LAUTSTAERKE);\\n  // Warte eine Sekunde\\n  delay(1000);\\n  // Mache den Summer aus\\n  analogWrite(SUMMER_PIN, 0); \\n  // Warte eine Sekunde\\n  delay(2000);\\n}\\n\" } } } }")])),
